package com.atelier.tasks.security;
import com.atelier.tasks.repository.UserRepository;import jakarta.servlet.*;import jakarta.servlet.http.*;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;import java.io.IOException;import java.util.List;
@Component public class JwtFilter extends OncePerRequestFilter {private final JwtService jwt;private final UserRepository users;public JwtFilter(JwtService j,UserRepository u){jwt=j;users=u;}@Override protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String h=req.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{String email=jwt.subject(h.substring(7));if(users.findByEmailIgnoreCase(email).isPresent())SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(email,null,List.of()));}catch(Exception ignored){}chain.doFilter(req,res);}}
